package com.company.tpm.attendance;import com.company.tpm.common.BaseEntity;import com.company.tpm.employee.Employee;import com.company.tpm.schedule.TrainingSession;import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="attendance",uniqueConstraints=@UniqueConstraint(columnNames={"session_id","employee_id"}))public class Attendance extends BaseEntity{@ManyToOne(optional=false,fetch=FetchType.LAZY)private TrainingSession session;@ManyToOne(optional=false,fetch=FetchType.LAZY)private Employee employee;@Enumerated(EnumType.STRING)@Column(nullable=false)private Status status;private String recordedBy;private Instant recordedAt;private String remark;public enum Status{PRESENT,ABSENT,LATE,EXCUSED}protected Attendance(){}public Attendance(TrainingSession s,Employee e,Status status,String actor){session=s;employee=e;this.status=status;recordedBy=actor;recordedAt=Instant.now();}public Status getStatus(){return status;}public void correct(Status next,String actor,String remark){status=next;recordedBy=actor;recordedAt=Instant.now();this.remark=remark;}}
